"""Shared API dependencies and helpers."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any

from app.core.config import settings
from app.schemas.common import DataProvenance

SIMULATED_NOTE = (
    "This response contains SIMULATED data generated by demo mode. It does "
    "not describe real satellite observations and must be labelled as "
    "simulated wherever it is displayed."
)


def make_provenance(
    source: str,
    records: list[dict[str, Any]] | None = None,
    notes: list[str] | None = None,
    evidence_key: str = "evidence_level",
    simulated_key: str = "is_simulated",
) -> DataProvenance:
    """Build the provenance block for a collection response.

    Scans the records for evidence levels and simulated flags so the envelope
    always reflects what is actually in the payload, rather than what the
    endpoint author assumed.
    """
    records = records or []
    levels: set[str] = set()
    simulated = False

    for record in records:
        level = record.get(evidence_key)
        if isinstance(level, str):
            levels.add(level)
        if record.get(simulated_key) or level == "SIMULATED":
            simulated = True

    all_notes = list(notes or [])
    if simulated and SIMULATED_NOTE not in all_notes:
        all_notes.insert(0, SIMULATED_NOTE)

    return DataProvenance(
        source=source,
        contains_simulated_data=simulated,
        evidence_levels=sorted(levels),
        generated_at=datetime.now(UTC),
        notes=all_notes,
    )


def demo_mode_notes() -> list[str]:
    """Standing notes to attach while the platform runs in demo mode."""
    if not settings.demo_mode:
        return []
    return [
        "DEMO_MODE is enabled. Satellite data may be synthetic; check "
        "'contains_simulated_data' on each response."
    ]
